def check_source(record, note):
    quote = record.get("source")
    if not isinstance(quote, str) or not quote or quote not in note:
        raise ValueError("Source text is absent from the note")
    return record

def exact_field_agreement(expected, actual, fields):
    return sum(expected.get(k) == actual.get(k) for k in fields) / len(fields)
assert exact_field_agreement({"owner": None}, {"owner": "Sam"}, ["owner"]) == 0
